begin;
select plan(29);
select has_column('public','lab_orders','accession_number','laboratory orders have server-generated accessions');
select has_column('public','lab_orders','facility_id','laboratory accession and QC are facility scoped');
select has_column('public','lab_orders','specimen_status','specimen state is tracked');
select has_table('public','lab_accession_counters','accessions use atomic facility/year counters');
select has_table('public','lab_specimen_events','specimen rejection events are preserved');
select has_table('public','lab_qc_rules','QC acceptance rules are configurable');
select has_table('public','lab_qc_runs','QC runs are recorded');
select has_table('public','lab_corrected_result_history','corrected results preserve history');
select has_table('public','radiology_report_history','radiology reports preserve revision history');
select has_view('public','lab_specimen_labels','specimen label view is available to the app print workflow');
select has_function('public','record_specimen_label_print',array['uuid','uuid'],'specimen label printing uses the audited in-app document path');
select has_column('public','radiology_orders','report_state','radiology report state is structured');
select has_function('public','configure_lab_qc_rule',array['uuid','text','text','jsonb'],'acceptance rules are configured through an RPC');
select has_function('public','record_lab_qc_run',array['uuid','text','text','numeric','timestamp with time zone'],'QC runs are evaluated server side');
select has_function('public','reject_lab_specimen',array['uuid','text'],'specimen rejection requires a reason through RPC');
select has_function('public','collect_lab_specimen',array['uuid'],'specimen collection is audited through RPC');
select has_trigger('public','lab_orders','assign_lab_accession','each order receives a server-generated accession');
select has_trigger('public','lab_orders','guard_lab_result_qc_and_correction','result release is guarded by latest QC');
select has_trigger('public','lab_orders','record_lab_corrected_result','corrected results are versioned');
select has_trigger('public','radiology_orders','aa_sync_radiology_report_state','structured states map to shared report status');
select has_trigger('public','radiology_orders','record_radiology_report_history','radiology report revisions are retained');
select has_trigger('public','radiology_orders','queue_radiology_result_acknowledgement','critical radiology results use the shared acknowledgement and escalation queue');
select ok(not has_table_privilege('authenticated','public.lab_qc_runs','INSERT'),'QC run inserts require the RPC');
select ok(not has_table_privilege('authenticated','public.lab_specimen_events','INSERT'),'specimen events require the RPC');
select like(pg_get_functiondef('public.guard_lab_result_qc_and_correction()'::regprocedure),'%latest QC for analyte % is missing or failed%','missing or failed latest QC blocks release');
select like(pg_get_functiondef('public.guard_lab_result_qc_and_correction()'::regprocedure),'%Rejected specimens cannot have released results%','rejected specimens cannot be released');
select like(pg_get_functiondef('public.configure_lab_qc_rule(uuid,text,text,jsonb)'::regprocedure),'%QC acceptance minimum cannot exceed maximum%','configurable acceptance bounds are validated');
select like(pg_get_functiondef('public.guard_lab_specimen_rejection()'::regprocedure),'%Use the specimen rejection workflow%','rejection requires audited reasoned workflow');
select like(pg_get_functiondef('public.collect_lab_specimen(uuid)'::regprocedure),'%specimen collection access denied%','specimen collection is facility authorized');
select * from finish();
rollback;
